#!/usr/bin/env bash
#
# setup-unix.sh - Deploy agent-dotfiles to Antigravity, Claude Code, OpenAI Codex, and GitHub Copilot
#
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BUILD_DIR="${SCRIPT_DIR}/build"

echo "==> [agents] Setting up agent configurations for Unix / macOS..."

# 1. Build consolidated rules (00-core + 10-unix + optional local override)
mkdir -p "${BUILD_DIR}"
cat > "${BUILD_DIR}/AGENTS.md" <<EOF
<!-- Generated by agent-dotfiles. Do not edit directly; edit agents/rules/*.md or local.md -->

EOF

cat "${SCRIPT_DIR}/rules/00-core.md" >> "${BUILD_DIR}/AGENTS.md"
echo "" >> "${BUILD_DIR}/AGENTS.md"
cat "${SCRIPT_DIR}/rules/10-unix.md" >> "${BUILD_DIR}/AGENTS.md"

if [[ -f "${SCRIPT_DIR}/AGENTS.local.md" ]]; then
  echo "==> [agents] Merging local override: AGENTS.local.md"
  echo "" >> "${BUILD_DIR}/AGENTS.md"
  cat "${SCRIPT_DIR}/AGENTS.local.md" >> "${BUILD_DIR}/AGENTS.md"
elif [[ -f "${SCRIPT_DIR}/rules/local.md" ]]; then
  echo "==> [agents] Merging local override: rules/local.md"
  echo "" >> "${BUILD_DIR}/AGENTS.md"
  cat "${SCRIPT_DIR}/rules/local.md" >> "${BUILD_DIR}/AGENTS.md"
fi

# 2. Deploy rules across agents
mkdir -p "${HOME}/.codex" "${HOME}/.copilot" "${HOME}/.claude"
ln -sf "${BUILD_DIR}/AGENTS.md" "${HOME}/.codex/AGENTS.md"
ln -sf "${BUILD_DIR}/AGENTS.md" "${HOME}/.copilot/copilot-instructions.md"
ln -sf "${BUILD_DIR}/AGENTS.md" "${HOME}/.claude/CLAUDE.md"
echo "  ✓ Linked rules to ~/.codex/AGENTS.md, ~/.copilot/copilot-instructions.md, and ~/.claude/CLAUDE.md"

AGY_CONFIG_DIR="${HOME}/.gemini/config"
if [[ -d "${AGY_CONFIG_DIR}" ]]; then
  ln -sf "${BUILD_DIR}/AGENTS.md" "${AGY_CONFIG_DIR}/AGENTS.md"
  echo "  ✓ Linked rules to ~/.gemini/config/AGENTS.md"
fi

# 3. Deploy skills (common + unix + local)
link_skills_to() {
  local target_dir="$1"
  mkdir -p "${target_dir}"

  # Clean up broken symlinks whose target no longer exists
  find "${target_dir}" -xtype l -delete 2>/dev/null || find "${target_dir}" -type l ! -exec test -e {} \; -delete 2>/dev/null || true

  for skill_cat in common unix local; do
    local src_cat_dir="${SCRIPT_DIR}/skills/${skill_cat}"
    if [[ -d "${src_cat_dir}" ]]; then
      for skill_path in "${src_cat_dir}"/*; do
        if [[ -d "${skill_path}" ]]; then
          local skill_name
          skill_name="$(basename "${skill_path}")"
          ln -sfn "${skill_path}" "${target_dir}/${skill_name}"
        fi
      done
    fi
  done
}

link_skills_to "${HOME}/.codex/skills"
link_skills_to "${HOME}/.copilot/skills"
link_skills_to "${HOME}/.claude/skills"
echo "  ✓ Linked skills to ~/.codex/skills, ~/.copilot/skills, and ~/.claude/skills"

if [[ -d "${AGY_CONFIG_DIR}" ]]; then
  link_skills_to "${AGY_CONFIG_DIR}/skills"
  echo "  ✓ Linked skills to ~/.gemini/config/skills"

  # Clean up legacy skills.json if present
  if [[ -f "${AGY_CONFIG_DIR}/skills.json" ]]; then
    rm -f "${AGY_CONFIG_DIR}/skills.json"
  fi
fi

echo "==> [agents] Deployment completed successfully!"
